import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.rules.CardInstance;
import java.util.*;

/** Card replacement preserves the logical Pokemon and its complete state, while physical card ownership stays separate. */
public final class PokemonCardReplacementFieldTest {
    static final UUID A=new UUID(0,5301),B=new UUID(0,5302);
    static void check(boolean b,String why){GeneratedRuleBatch8Test.check(b,why);}
    static CardInstance card(UUID owner,int n,String id){return new CardInstance(new UUID(owner.getLeastSignificantBits(),n),owner,id);}
    static BattlefieldState field(ServerRandom random){var ability=new AbilityDefinition("used","used",new AbilityEffect(AbilityEffect.Opcode.DRAW,1,0),dev.hua.ptcglive.rules.EffectSupport.SUPPORTED,null);var base=new PokemonProfile(200,0,null,null,0,null,0,1,List.of(),List.of(ability),EnergyType.COLORLESS);var other=new PokemonProfile(300,0,null,EnergyType.DARKNESS,2,null,0,2,List.of(),List.of(ability,new AbilityDefinition("different","different",new AbilityEffect(AbilityEffect.Opcode.DRAW,1,0),dev.hua.ptcglive.rules.EffectSupport.SUPPORTED,null)),EnergyType.PSYCHIC);var evolved=new PokemonProfile(250,0,"base",null,0,null,0,1,List.of(),List.of(ability),EnergyType.FIGHTING);var f=new BattlefieldState(A,B,Map.of("base",base,"other",other,"evolved",evolved,"other-evolved",new PokemonProfile(400,0,"other")),random);f.placeInitialActive(A,card(A,1,"base"));f.placeInitialActive(B,card(B,1,"base"));f.beginTurn(A);return f;}
    public static void main(String[] args){preservedState();stackAndAuthority();releasedCardReturns();evolutionTiming();statusTiming();abilityUsage();privacy();deterministic();System.out.println("PokemonCardReplacementFieldTest passed: top-only physical replacement keeps logical identity, entry/timing/abilities/attachments/history/status/all continuous and delayed state, lower evolution cards, new profile and future evolution; released physical card can reenter with independent deterministic field ID, no game RNG or duplicate physical placements");}
    static void preservedState(){var rng=new ServerRandom(53);var f=field(rng);UUID id=f.activeView(A).pokemonId();long life=f.pokemonEntrySequence(A,id);CardInstance energy=card(B,5,"energy"),tool=card(A,6,"tool");f.attachEnergyByEffect(A,id,energy);f.attachToolByEffect(A,id,tool,1);long attached=f.attachmentEntrySequence(A,id,energy.instanceId());f.placeDamageCounters(A,id,8);f.applySpecialCondition(A,SpecialCondition.POISONED,3);f.applySpecialCondition(A,SpecialCondition.BURNED,4);f.applySpecialCondition(A,SpecialCondition.CONFUSED);f.healByEffect(A,id,10);f.recordOpponentAttackDamage(A,id,7,70);f.beginAbility(A,id,"used");f.reduceDamageFromOpponentNextTurn(A,id,B,20);f.disableAbilityEffectsUntilOwnerNextTurn(A,A,id);f.overwriteWeaknessThroughOwnerNextTurn(B,A,id,null,false);UUID token=new UUID(53,8);f.addDelayedMarker(A,id,token,"delayed");var old=f.activeView(A);int random=rng.transcript().size();var selected=card(A,9,"other");var returned=f.replaceTopCardByEffect(A,id,selected);var now=f.activeView(A);check(!returned.instanceId().equals(id)&&now.pokemonId().equals(id)&&f.topCard(A,id).equals(selected)&&now.hitPoints()==300&&f.pokemonEntrySequence(A,id)==life,"Card swap replaced logical identity/life or retained printed profile");check(now.damage()==old.damage()&&now.conditions().equals(old.conditions())&&now.attachedEnergyIds().equals(old.attachedEnergyIds())&&now.attachedTools().equals(old.attachedTools())&&now.continuousEffectZh().equals(old.continuousEffectZh())&&f.hasDelayedMarker(A,id,token),"Card swap dropped preserved public or delayed state");check(f.attachmentEntrySequence(A,id,energy.instanceId())==attached&&f.abilityUsed(A,id,"used")&&f.attackDamageReceivedInTurn(A,id,7)==70&&rng.transcript().size()==random,"Card swap renewed attachment/ability/history or used game RNG");}
    static void stackAndAuthority(){var f=field(new ServerRandom(1));UUID id=f.activeView(A).pokemonId();var evolution=card(A,2,"evolved");f.evolve(A,id,evolution,EvolutionPermission.CARD_EFFECT_ALL_TIMING);var replacement=card(A,3,"other");check(f.replaceTopCardByEffect(A,id,replacement).equals(evolution)&&f.activeView(A).evolutionCardIds().equals(List.of("base","other")),"Replacement removed lower evolution cards or returned more than old top");var before=f.activeView(A);for(Runnable bad:List.<Runnable>of(()->f.replaceTopCardByEffect(B,id,card(B,4,"other")),()->f.replaceTopCardByEffect(A,id,replacement),()->f.replaceTopCardByEffect(A,id,card(A,1,"base")),()->f.placeOnBench(A,replacement),()->f.replaceTopCardByEffect(A,id,card(A,7,"missing")))){GeneratedRuleBatch8Test.reject(bad);check(f.activeView(A).equals(before),"Invalid physical/source replacement mutated field");}}
    static void releasedCardReturns(){var f=field(new ServerRandom(2));UUID old=f.activeView(A).pokemonId();var physical=f.replaceTopCardByEffect(A,old,card(A,20,"other"));long original=f.pokemonEntrySequence(A,old);f.placeOnBench(A,physical);var returned=f.benchView(A).getFirst();check(!returned.pokemonId().equals(old)&&f.topCard(A,returned.pokemonId()).equals(physical)&&f.pokemonEntrySequence(A,returned.pokemonId())!=original,"Released original physical card duplicated transformed logical identity or stay");f.placeDamageCounters(A,old,2);check(f.activeView(A).damage()==20&&f.benchView(A).getFirst().damage()==0,"Captured old logical reference targeted reentered old card");f.switchActiveByEffect(A,returned.pokemonId());check(f.activeView(A).topCardId().equals("base")&&f.benchView(A).getFirst().topCardId().equals("other"),"Field command confused physical card ID with new logical identity");}
    static void evolutionTiming(){var f=field(new ServerRandom(4));UUID id=f.activeView(A).pokemonId();f.beginTurn(B);f.beginTurn(A);long life=f.pokemonEntrySequence(A,id);f.replaceTopCardByEffect(A,id,card(A,40,"other"));check(f.canEvolve(A,id,"other-evolved"),"Replacement reset turns in play or was counted as evolution");f.evolve(A,id,card(A,41,"other-evolved"));check(f.pokemonEntrySequence(A,id)==life&&f.activeView(A).evolutionCardIds().equals(List.of("other","other-evolved")),"Normal evolution after replacement lost logical life or used released lower card");}
    static void statusTiming(){
        for(var status:List.of(SpecialCondition.CONFUSED,SpecialCondition.ASLEEP,SpecialCondition.PARALYZED)){
            var f=field(new ServerRandom(5));UUID id=f.activeView(A).pokemonId();f.placeDamageCounters(A,id,3);f.healByEffect(A,id,10);
            f.applySpecialCondition(A,SpecialCondition.POISONED,3);f.applySpecialCondition(A,SpecialCondition.BURNED,4);f.applySpecialCondition(A,status);
            boolean became=f.becameActiveThisTurn(A,id);f.replaceTopCardByEffect(A,id,card(A,50,"other"));
            check(f.checkupCounters(A,SpecialCondition.POISONED)==3&&f.checkupCounters(A,SpecialCondition.BURNED)==4&&f.healedThisTurn(A,id)&&f.becameActiveThisTurn(A,id)==became,"Replacement reset stronger status counters or turn facts");
            var first=f.pokemonCheckup();check(f.activeView(A).damage()==90&&f.activeView(A).conditions().contains(status)==(status!=SpecialCondition.ASLEEP||first.events().stream().filter(e->e.condition()==SpecialCondition.ASLEEP).findFirst().orElseThrow().coin()==CoinSide.TAILS),"Replacement changed status recovery or Checkup counter amounts");
            if(status==SpecialCondition.PARALYZED){f.beginTurn(B);f.pokemonCheckup();check(f.activeView(A).conditions().contains(status),"Replacement renewed or prematurely cleared Paralysis");f.beginTurn(A);f.pokemonCheckup();check(!f.activeView(A).conditions().contains(status),"Replacement lost original owner-turn Paralysis expiry");}
        }
        var f=field(new ServerRandom(6));UUID id=f.activeView(A).pokemonId();f.beginTurn(B);f.beginTurn(A);f.evolve(A,id,card(A,60,"evolved"));f.replaceTopCardByEffect(A,id,card(A,61,"other"));check(!f.canEvolve(A,id,"other-evolved"),"Top-card replacement reset already-evolved-this-turn restriction");
    }
    static void abilityUsage(){var f=field(new ServerRandom(7));UUID id=f.activeView(A).pokemonId();f.beginAbility(A,id,"used");f.replaceTopCardByEffect(A,id,card(A,70,"other"));GeneratedRuleBatch8Test.reject(()->f.beginAbility(A,id,"used"));check(!f.abilityUsed(A,id,"different"),"Old used Ability prevented an unrelated new Ability");f.beginAbility(A,id,"different");check(f.abilityUsed(A,id,"different")&&f.abilityUsed(A,id,"used"),"Replacement did not keep separate per-Ability usage");}
    static void privacy(){var f=field(new ServerRandom(53));UUID logical=f.activeView(A).pokemonId();var returned=f.replaceTopCardByEffect(A,logical,card(A,80,"other"));check(!f.activeView(A).toString().contains(returned.instanceId().toString()),"Returned hidden card remains exposed through current field identity");}
    static void deterministic(){var ids=new ArrayList<UUID>();for(int i=0;i<2;i++){var rng=new ServerRandom(3);var f=field(rng);UUID old=f.activeView(A).pokemonId();var card=f.replaceTopCardByEffect(A,old,card(A,30,"other"));int random=rng.transcript().size();f.placeOnBench(A,card);ids.add(f.benchView(A).getFirst().pokemonId());check(rng.transcript().size()==random,"Collision identity allocation spent game RNG");}check(ids.getFirst().equals(ids.getLast()),"Identity allocation cannot be reproduced from the same field entries");}
}
